const generic=/^(explain more|explain simply|another fact|tell me more|why|ပိုမိုရှင်းပြပါ|ရိုးရိုးရှင်းပြပါ|နောက်အချက်တစ်ခု|详细解释|简单解释|另一条知识)[?？.! ]*$/i;
const norm=s=>s.toLowerCase().replace(/[?？။.!]/g,'').trim();
export function matchTopic(text){const value=norm(text);return topics.find(t=>Object.values(t.questions).flat().some(q=>norm(q)===value))||topics.find(t=>t.aliases.some(a=>value.includes(a)))||null;}
export function resolveTopic(text,history=[]){const explicit=matchTopic(text);if(explicit)return {topic:explicit,follow:false};if(/\b(?:mercury|venus|earth|mars|jupiter|saturn|uranus|neptune|sun|moon|black holes?|milky way)\b/i.test(text)||names.zh.some(n=>text.includes(n))||names.my.slice(0,8).some(n=>text.includes(n)))return {topic:null,follow:false};const dependent=generic.test(text)||/\b(it|they|them|its|their|those)\b/i.test(text)||/它|它们|၎င်း/.test(text);if(!dependent)return {topic:null,follow:false};for(const turn of [...history].reverse()){if(turn.role==='user'){const topic=matchTopic(turn.content);if(topic)return {topic,follow:true};}}return {topic:null,follow:false};}
export function relatedQuestions(text,history,lang){const {topic}=resolveTopic(text,history);const seen=new Set([text,...history.filter(t=>t.role==='user').map(t=>t.content)].map(norm));return (topic?.questions[lang]||[]).filter(q=>!seen.has(norm(q))).slice(0,3);}
export function topicReference(topic,lang){return {title:topic.term,excerpt:topic.notes[lang],url:topic.source,language:lang,provider:'ORBIT summary · NASA source'};}
